* DODF1 -- DODFMR with Record PEBD comparison
MAP DODF1 SIZE 24x80

  FIELD AT 1,18 LEN 45 PROT BRIGHT COLOR=TURQUOISE "DODFMR STATEMENT OF SERVICE CALCULATOR"

  FIELD AT 3,5  LEN 6 PROT "EDIPI:"
  INPUT EDIPI AT 3,12 LEN 10 COLOR=GREEN
  FIELD AT 3,28 LEN 6 PROT "NAME:"
  INPUT NAME  AT 3,35 LEN 30 COLOR=GREEN

  FIELD AT 4,5  LEN 8 PROT "AS OF:"
  INPUT ASOF     AT 4,14 LEN 8 COLOR=GREEN UNDERSCORE
  FIELD AT 4,25 LEN 35 PROT DIM "(blank = today)"

  FIELD AT 5,5  LEN 12 PROT "RECORD PEBD:"
  INPUT RECPEBD  AT 5,18 LEN 8 COLOR=GREEN UNDERSCORE
  FIELD AT 5,28 LEN 35 PROT DIM "(optional - for comparison)"

  FIELD AT 7,5 LEN 70 PROT BRIGHT COLOR=BLUE "*** SERVICE PERIODS (enter up to 8) ***"

  FIELD AT 9,5  LEN 6 PROT COLOR=BLUE "FROM"
  FIELD AT 9,16 LEN 6 PROT COLOR=BLUE "TO"
  FIELD AT 9,27 LEN 6 PROT COLOR=BLUE "BRCH"
  FIELD AT 9,34 LEN 5 PROT COLOR=BLUE "COMP"
  FIELD AT 9,41 LEN 7 PROT COLOR=BLUE "REASON"
  FIELD AT 9,50 LEN 6 PROT COLOR=BLUE "LOST"

  INPUT FROM1 AT 10,5  LEN 10 COLOR=GREEN UNDERSCORE
  INPUT TO1   AT 10,16 LEN 10 COLOR=GREEN UNDERSCORE
  INPUT BR1   AT 10,27 LEN 4  COLOR=GREEN UNDERSCORE
  INPUT CP1   AT 10,34 LEN 3  COLOR=GREEN UNDERSCORE
  INPUT RS1   AT 10,41 LEN 6  COLOR=GREEN UNDERSCORE
  INPUT LT1   AT 10,50 LEN 6  COLOR=GREEN UNDERSCORE

  INPUT FROM2 AT 11,5  LEN 10 COLOR=GREEN UNDERSCORE
  INPUT TO2   AT 11,16 LEN 10 COLOR=GREEN UNDERSCORE
  INPUT BR2   AT 11,27 LEN 4  COLOR=GREEN UNDERSCORE
  INPUT CP2   AT 11,34 LEN 3  COLOR=GREEN UNDERSCORE
  INPUT RS2   AT 11,41 LEN 6  COLOR=GREEN UNDERSCORE
  INPUT LT2   AT 11,50 LEN 6  COLOR=GREEN UNDERSCORE

  INPUT FROM3 AT 12,5  LEN 10 COLOR=GREEN UNDERSCORE
  INPUT TO3   AT 12,16 LEN 10 COLOR=GREEN UNDERSCORE
  INPUT BR3   AT 12,27 LEN 4  COLOR=GREEN UNDERSCORE
  INPUT CP3   AT 12,34 LEN 3  COLOR=GREEN UNDERSCORE
  INPUT RS3   AT 12,41 LEN 6  COLOR=GREEN UNDERSCORE
  INPUT LT3   AT 12,50 LEN 6  COLOR=GREEN UNDERSCORE

  INPUT FROM4 AT 13,5  LEN 10 COLOR=GREEN UNDERSCORE
  INPUT TO4   AT 13,16 LEN 10 COLOR=GREEN UNDERSCORE
  INPUT BR4   AT 13,27 LEN 4  COLOR=GREEN UNDERSCORE
  INPUT CP4   AT 13,34 LEN 3  COLOR=GREEN UNDERSCORE
  INPUT RS4   AT 13,41 LEN 6  COLOR=GREEN UNDERSCORE
  INPUT LT4   AT 13,50 LEN 6  COLOR=GREEN UNDERSCORE

  INPUT FROM5 AT 14,5  LEN 10 COLOR=GREEN UNDERSCORE
  INPUT TO5   AT 14,16 LEN 10 COLOR=GREEN UNDERSCORE
  INPUT BR5   AT 14,27 LEN 4  COLOR=GREEN UNDERSCORE
  INPUT CP5   AT 14,34 LEN 3  COLOR=GREEN UNDERSCORE
  INPUT RS5   AT 14,41 LEN 6  COLOR=GREEN UNDERSCORE
  INPUT LT5   AT 14,50 LEN 6  COLOR=GREEN UNDERSCORE

  INPUT FROM6 AT 15,5  LEN 10 COLOR=GREEN UNDERSCORE
  INPUT TO6   AT 15,16 LEN 10 COLOR=GREEN UNDERSCORE
  INPUT BR6   AT 15,27 LEN 4  COLOR=GREEN UNDERSCORE
  INPUT CP6   AT 15,34 LEN 3  COLOR=GREEN UNDERSCORE
  INPUT RS6   AT 15,41 LEN 6  COLOR=GREEN UNDERSCORE
  INPUT LT6   AT 15,50 LEN 6  COLOR=GREEN UNDERSCORE

  INPUT FROM7 AT 16,5  LEN 10 COLOR=GREEN UNDERSCORE
  INPUT TO7   AT 16,16 LEN 10 COLOR=GREEN UNDERSCORE
  INPUT BR7   AT 16,27 LEN 4  COLOR=GREEN UNDERSCORE
  INPUT CP7   AT 16,34 LEN 3  COLOR=GREEN UNDERSCORE
  INPUT RS7   AT 16,41 LEN 6  COLOR=GREEN UNDERSCORE
  INPUT LT7   AT 16,50 LEN 6  COLOR=GREEN UNDERSCORE

  INPUT FROM8 AT 17,5  LEN 10 COLOR=GREEN UNDERSCORE
  INPUT TO8   AT 17,16 LEN 10 COLOR=GREEN UNDERSCORE
  INPUT BR8   AT 17,27 LEN 4  COLOR=GREEN UNDERSCORE
  INPUT CP8   AT 17,34 LEN 3  COLOR=GREEN UNDERSCORE
  INPUT RS8   AT 17,41 LEN 6  COLOR=GREEN UNDERSCORE
  INPUT LT8   AT 17,50 LEN 6  COLOR=GREEN UNDERSCORE

  FIELD AT 19,5 LEN 60 PROT DIM COLOR=BLUE "PF3=Exit   ENTER=Calculate   F9=Clear All"
  CURSOR AT EDIPI
ENDMAP